package tmplc

import (
	"fmt"
	"go/format"
	"maps"
	"slices"
	"strconv"
	"strings"
)

// source is the generated file. left holds the fingerprints of the
// templates of the package's sets that have no code, which
// tmplrt.RegisterOwner must know to tell them from stale ones.
func (generated *file) source(left []string) ([]byte, error) {
	fields := generated.funcFields()
	var builder strings.Builder
	generated.writeHeader(&builder, generated.imported(fields))
	fps := slices.Sorted(maps.Keys(generated.binds))
	bindNames, err := generated.writeInit(&builder, left, fps)
	if err != nil {
		return nil, err
	}
	if len(generated.bodies) > 0 {
		generated.writeFuncsStruct(&builder, fields)
	}
	for _, fp := range fps {
		generated.writeBind(&builder, fp)
	}
	for _, name := range slices.Sorted(maps.Keys(generated.bodies)) {
		function := generated.bodies[name]
		fmt.Fprintf(&builder, "\n// %s %s\nfunc %s%s",
			name, function.doc, name, function.code)
		if len(function.facts) > 0 {
			generated.writeFacts(&builder, name, function.assumed)
		}
	}
	if err := generated.checkNames(bindNames); err != nil {
		return nil, err
	}
	src, err := format.Source([]byte(builder.String()))
	if err != nil {
		return nil, fmt.Errorf(
			"tmplc: generated code for %s does not parse: %w\n%s",
			generated.in.PkgPath,
			err,
			builder.String(),
		)
	}
	return src, nil
}

// funcFields is the funcs struct's fields: every function a bind
// binds, by field.
func (generated *file) funcFields() map[string]*fn {
	fields := map[string]*fn{}
	for _, bd := range generated.binds {
		for _, fn := range bd.fns {
			fields[fn.field] = fn
		}
	}
	return fields
}

// imported is the file's imports: the packages the types of fields
// name, and those the code itself uses.
func (generated *file) imported(fields map[string]*fn) map[string]string {
	imports := map[string]string{}
	for _, fn := range fields {
		maps.Copy(imports, fn.qualifiers)
	}
	if len(generated.bodies) > 0 {
		imports[generated.bytes] = "bytes"
		imports[generated.reflect] = "reflect"
	}
	imports[generated.rt] = tmplrtPath
	return imports
}

// The generated file's header lines.
const (
	generatedHeader = "// Code generated by rastrillo generate; " +
		"DO NOT EDIT.\n\n" +
		"//go:build !rastrillo_capture && !rastrillo_dev\n\n"
	lintHeader = "//lint:file-ignore SA4* this file spells out the " +
		"templates' own logic, which may compare a value with itself " +
		"or leave a loop at once\n\n"
)

// writeHeader writes the file's header, package clause and imports.
func (generated *file) writeHeader(
	builder *strings.Builder,
	imports map[string]string,
) {
	// rastrillo_capture leaves the file out of capture, so a stale one
	// that no longer compiles cannot block its own regeneration;
	// rastrillo_dev leaves it out of rastrillo dev, which renders the
	// templates on disk and must not break when a field they read is
	// renamed.
	builder.WriteString(generatedHeader)
	// Staticcheck's SA4 checks report code that does nothing, and a
	// faithful translation of a template writes some: {{eq .A .A}}
	// compares a value with itself, {{range}}{{break}} is a loop that
	// always exits, and a $ assigned last is never read. They are the
	// template's to answer for, and an app's own staticcheck, which
	// runs over ./..., would otherwise fail on code it cannot edit.
	builder.WriteString(lintHeader)
	fmt.Fprintf(builder, "package %s\n\n", generated.in.PkgName)
	builder.WriteString("import (\n")
	byPath := func(first, second string) int {
		return strings.Compare(imports[first], imports[second])
	}
	for _, name := range slices.SortedFunc(maps.Keys(imports), byPath) {
		writeImport(builder, name, imports[name])
	}
	builder.WriteString(")\n\n")
}

// writeInit writes the init function, which registers the owner and
// each bind, and returns the binds' names, each with its fingerprint.
func (generated *file) writeInit(
	builder *strings.Builder,
	left, fps []string,
) (map[string]string, error) {
	bindNames := map[string]string{}
	builder.WriteString("func init() {\n")
	// tmpl records a set built in a main package under "main", the name
	// the runtime gives its functions; a binary links only one.
	owner := generated.in.PkgPath
	if generated.in.PkgName == "main" {
		owner = "main"
	}
	fmt.Fprintf(builder, "\t%s.RegisterOwner(%q, %s)\n",
		generated.rt, owner, stringSlice(left))
	for _, fp := range fps {
		name := bindName(fp)
		if prior, taken := bindNames[name]; taken {
			return nil, fmt.Errorf(
				"tmplc: fingerprints %s and %s share the prefix %s",
				prior,
				fp,
				name,
			)
		}
		bindNames[name] = fp
		fmt.Fprintf(builder, "\t%s.Register(%q, %s)\n",
			generated.rt, fp, name)
	}
	builder.WriteString("}\n")
	return bindNames, nil
}

// bindName is the name of the bind of the fingerprint fp.
func bindName(fp string) string {
	return "bind_" + fp[:min(len(fp), prefixLen)]
}

// funcsDoc is the funcs struct's doc comment and declaration.
const funcsDoc = "\n// %s holds the FuncMap functions the code calls, " +
	"which a Bind\n// takes from its set once.\ntype %s struct {\n"

// writeFuncsStruct writes the funcs struct, with a field for each
// function of fields: of its own type when it is called directly, a
// reflect.Value when not.
func (generated *file) writeFuncsStruct(
	builder *strings.Builder,
	fields map[string]*fn,
) {
	fmt.Fprintf(builder, funcsDoc, generated.funcs, generated.funcs)
	for _, field := range slices.Sorted(maps.Keys(fields)) {
		fn := fields[field]
		if fn.direct {
			fmt.Fprintf(builder, "\t%s %s\n", field, fn.expr)
		} else {
			fmt.Fprintf(builder, "\t%s %s.Value\n", field, generated.reflect)
		}
	}
	builder.WriteString("}\n")
}

// writeBind writes the bind of the fingerprint fp: it takes the set's
// functions, checks the facts, and returns the Exec that runs a typed
// variant or the code that reads by reflection.
func (generated *file) writeBind(builder *strings.Builder, fp string) {
	bd := generated.binds[fp]
	name := bindName(fp)
	// Recover and Data stand where text/template's Execute catches a
	// panicking function and makes the data a reflect.Value; a
	// {{template}} call does neither, so they are here and not in the
	// body.
	fmt.Fprintf(builder, "\n// %s binds %q.\n", name, bd.entry)
	fns := generated.writeBindFuncs(builder, name, bd.fns)
	typedOK := generated.writeHolds(builder, bd)
	fmt.Fprintf(builder,
		"\treturn func(b *%s.Buffer, data any) (err error) {\n",
		generated.bytes)
	fmt.Fprintf(builder, "\t\tdefer %s.Recover(&err, %q)\n",
		generated.rt, bd.entry)
	if len(bd.typed) > 0 {
		builder.WriteString("\t\tswitch data := data.(type) {\n")
		for index, variant := range bd.typed {
			fmt.Fprintf(builder, typedCaseCode,
				variant.typ, typedOK[index], variant.fn, fns)
		}
		builder.WriteString("\t\t}\n")
	}
	fmt.Fprintf(builder, "\t\treturn %s(b, %s.Data(data), %s, 0)\n",
		bd.body, generated.rt, fns)
	builder.WriteString("\t}, nil\n}\n")
}

// typedCaseCode is the case of a bind's type switch that runs a typed
// variant, if its facts hold.
const typedCaseCode = "\t\tcase %s:\n\t\t\tif %s {\n" +
	"\t\t\t\treturn %s(b, data, %s, 0)\n\t\t\t}\n"

// writeBindFuncs writes the bind's signature, called name, and the
// code that takes fns from the set's FuncMap, and returns what the
// bind passes its bodies for them.
func (generated *file) writeBindFuncs(
	builder *strings.Builder,
	name string,
	fns []*fn,
) string {
	if len(fns) == 0 {
		fmt.Fprintf(builder, "func %s(map[string]any) (%s.Exec, error) {\n",
			name, generated.rt)
		return "nil"
	}
	fmt.Fprintf(builder,
		"func %s(funcs map[string]any) (%s.Exec, error) {\n",
		name, generated.rt)
	fmt.Fprintf(builder, "\tfn := new(%s)\n", generated.funcs)
	if slices.ContainsFunc(fns, func(fn *fn) bool { return fn.direct }) {
		builder.WriteString("\tvar ok bool\n")
	}
	for _, fn := range fns {
		if fn.direct {
			fmt.Fprintf(builder, "\tif fn.%s, ok = funcs[%q].(%s); !ok {\n",
				fn.field, fn.name, fn.expr)
		} else {
			fmt.Fprintf(builder, "\tif fn.%s = %s.ValueOf(funcs[%q]); "+
				"fn.%s.Kind() != %s.Func {\n",
				fn.field, generated.reflect, fn.name, fn.field,
				generated.reflect)
		}
		fmt.Fprintf(builder,
			"\t\treturn nil, %s.BindError(%q, funcs[%q])\n\t}\n",
			generated.rt, fn.name, fn.name)
	}
	return "fn"
}

// writeHolds writes the bind's checks of the facts its code assumes,
// and returns the names of the booleans that say whether each typed
// variant's facts hold.
func (generated *file) writeHolds(
	builder *strings.Builder,
	bd bind,
) []string {
	// Code compiled for types the program no longer has is not run:
	// a typed variant is left out, and the data it was for takes the
	// code that reads by reflection; code that fails otherwise is
	// refused, and the set runs html/template.
	if held := generated.held(bd.bodies...); held != "" {
		fmt.Fprintf(builder,
			"\tif err := %s.Holds(%s); err != nil {\n"+
				"\t\treturn nil, err\n\t}\n",
			generated.rt, held)
	}
	typedOK := make([]string, len(bd.typed))
	for index, variant := range bd.typed {
		typedOK[index] = fmt.Sprintf("typed%d", index)
		fmt.Fprintf(builder, "\t%s := %s.Holds(%s) == nil\n",
			typedOK[index], generated.rt,
			generated.held(generated.reached(variant.fn)...))
	}
	return typedOK
}

// checkNames fails when the package declares a name the generated file
// needs: a bind's, a function's or a function's facts'.
func (generated *file) checkNames(bindNames map[string]string) error {
	const taken = "tmplc: package %s declares %s, " +
		"which the generated file needs"
	for name := range bindNames {
		if generated.declared(name) {
			return fmt.Errorf(taken, generated.in.PkgPath, name)
		}
	}
	for name, bd := range generated.bodies {
		if generated.declared(name) {
			return fmt.Errorf(taken, generated.in.PkgPath, name)
		}
		if len(bd.facts) > 0 && generated.declared(factsName(name)) {
			return fmt.Errorf(taken, generated.in.PkgPath, factsName(name))
		}
	}
	return nil
}

func (generated *file) declared(name string) bool {
	return generated.in.Types != nil &&
		generated.in.Types.Scope().Lookup(name) != nil
}

func writeImport(builder *strings.Builder, name, path string) {
	if name == path[strings.LastIndexByte(path, '/')+1:] {
		fmt.Fprintf(builder, "\t%q\n", path)
		return
	}
	fmt.Fprintf(builder, "\t%s %q\n", name, path)
}

func stringSlice(names []string) string {
	if len(names) == 0 {
		return "nil"
	}
	quoted := make([]string, len(names))
	for index, name := range names {
		quoted[index] = strconv.Quote(name)
	}
	return "[]string{" + strings.Join(quoted, ", ") + "}"
}
